/** A tool's icon by its id in [TOOLS], or null. */
fun toolIcon(id: String): ImageVector? = when (id) {
    "Select" -> Lucide.MousePointer2
    "Shape" -> Lucide.Shapes
    "TextBox" -> Lucide.Type
    "Ink" -> Lucide.PenLine
    else -> null
}

